    parts = []
    for m in run.transcript:
        for b in m.content:
            t = b.get("type")
            if t == "text":
                parts.append(f"[{m.role}] {b['text']}")
            elif t == "tool_use":
                parts.append(f"[{m.role}->tool] {b['name']}({json.dumps(b['input'])})")
            elif t == "tool_result":
                parts.append(f"[tool_result] {b['content']}")
    rendered = "\n".join(parts)
    return rendered[-max_chars:]


